/// 1024 实心图标（fill 模式，与 PortenBackIcon 同构）。
class PortenGlyphIcon extends StatelessWidget {
  const PortenGlyphIcon(this.name, {super.key, this.size = 20, this.color = const Color(0xFF1A1A1A)});

  final String name;
  final double size;
  final Color color;

  @override
  Widget build(BuildContext context) {
    final List<String>? paths = kPortenGlyphPaths[name];
    assert(paths != null, 'PortenGlyphIcon: unknown glyph "$name"');
    return SizedBox(
      width: size,
      height: size,
      child: CustomPaint(painter: _GlyphPainter(paths ?? const <String>[], color)),
    );
  }
}

class _GlyphPainter extends CustomPainter {
  _GlyphPainter(this.paths, this.color);

  final List<String> paths;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final double scale = size.width / 1024;
    final Paint paint = Paint()
      ..color = color
      ..style = PaintingStyle.fill;
    canvas.save();
    canvas.scale(scale, scale);
    for (final String d in paths) {
      if (d.isEmpty) continue;
      canvas.drawPath(svgPathToUiPath(d), paint);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _GlyphPainter oldDelegate) =>
      oldDelegate.color != color;
}
